import 'package:flutter/material.dart';import '../widgets/search_view_body.dart';class SearchScreen extends StatelessWidget {  const SearchScreen({super.key});  @override  Widget build(BuildContext context) {    return SlideTransition(      position: Tween<Offset>(        begin: const Offset(0, 1),        end: Offset.zero,      ).animate(        CurvedAnimation(          parent: ModalRoute.of(context)!.animation!,          curve: Curves.easeInOut,        ),      ),      child: const SearchViewBody(),    );  }}